[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap" rel="stylesheet" />
  <style>
    /* ─── DESIGN TOKENS ─────────────────────────────────── */
    :root {
      --teal:        oklch(52% 0.12 195);
      --teal-light:  oklch(94% 0.04 195);
      --teal-dark:   oklch(38% 0.11 195);
      --coral:       oklch(65% 0.17 30);
      --coral-light: oklch(95% 0.04 30);
      --amber:       oklch(72% 0.16 60);
      --charcoal:    oklch(18% 0.01 260);
      --ink:         oklch(28% 0.01 260);
      --muted:       oklch(50% 0.01 260);
      --border:      oklch(90% 0.01 260);
      --surface:     oklch(97% 0.005 200);
      --white:       oklch(100% 0 0);
      --tag-bg:      oklch(93% 0.04 195);

      --radius-sm:   6px;
      --radius-md:   12px;
      --radius-lg:   20px;
      --radius-xl:   28px;

      --shadow-sm:   0 1px 4px oklch(18% 0.01 260 / 0.08);
      --shadow-md:   0 4px 16px oklch(18% 0.01 260 / 0.10);
      --shadow-lg:   0 8px 32px oklch(18% 0.01 260 / 0.13);

      --font: 'DM Sans', system-ui, -apple-system, sans-serif;
      --max-w: 1200px;
      --transition: 200ms ease;
    }

    /* ─── RESET ─────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font);
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { font-family: var(--font); cursor: pointer; border: none; background: none; }
    ul { list-style: none; }

    /* ─── LAYOUT HELPERS ────────────────────────────────── */
    .container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }
    .section { padding: 64px 0; }
    .section--alt { background: var(--surface); }

    /* ─── HEADER ─────────────────────────────────────────── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: var(--white);
      border-bottom: 1px solid var(--border);
      box-shadow: var(--shadow-sm);
    }
    .header__inner {
      display: flex;
      align-items: center;
      gap: 32px;
      height: 64px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-shrink: 0;
    }
    .logo__mark {
      width: 36px;
      height: 36px;
      background: var(--teal);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
    }
    .logo__mark svg { width: 20px; height: 20px; }
    .logo__text {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--charcoal);
      letter-spacing: -0.3px;
    }
    .logo__text span { color: var(--teal); }

    /* ─── NAV ────────────────────────────────────────────── */
    .nav { flex: 1; }
    .nav__list {
      display: flex;
      gap: 4px;
      align-items: center;
    }
    .nav__item { position: relative; }
    .nav__link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 14px;
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--ink);
      border-radius: var(--radius-sm);
      transition: background var(--transition), color var(--transition);
      white-space: nowrap;
    }
    .nav__link:hover, .nav__item--open .nav__link {
      background: var(--teal-light);
      color: var(--teal);
    }
    .nav__arrow {
      width: 14px;
      height: 14px;
      transition: transform var(--transition);
    }
    .nav__item--open .nav__arrow { transform: rotate(180deg); }

    /* Mega-menu dropdown */
    .dropdown {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      min-width: 280px;
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      padding: 20px;
      opacity: 0;
      pointer-events: none;
      transform: translateY(-8px);
      transition: opacity var(--transition), transform var(--transition);
      z-index: 200;
    }
    .nav__item--open .dropdown {
      opacity: 1;
      pointer-events: auto;
      transform: translateY(0);
    }
    .dropdown--wide { min-width: 560px; }
    .dropdown__heading {
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--muted);
      margin-bottom: 10px;
    }
    .dropdown__grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 2px;
    }
    .dropdown__link {
      display: block;
      padding: 6px 10px;
      font-size: 0.875rem;
      color: var(--ink);
      border-radius: var(--radius-sm);
      transition: background var(--transition), color var(--transition);
    }
    .dropdown__link:hover { background: var(--teal-light); color: var(--teal); }
    .dropdown__section { margin-bottom: 16px; }
    .dropdown__section:last-child { margin-bottom: 0; }
    .dropdown__divider { height: 1px; background: var(--border); margin: 12px 0; }

    .header__actions {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-shrink: 0;
    }
    .btn { display: inline-flex; align-items: center; gap: 6px; border-radius: var(--radius-sm); font-weight: 600; font-size: 0.875rem; transition: all var(--transition); padding: 8px 18px; }
    .btn--ghost { border: 1.5px solid var(--border); color: var(--ink); }
    .btn--ghost:hover { border-color: var(--teal); color: var(--teal); background: var(--teal-light); }
    .btn--primary { background: var(--teal); color: var(--white); }
    .btn--primary:hover { background: var(--teal-dark); }
    .btn--coral { background: var(--coral); color: var(--white); }
    .btn--coral:hover { filter: brightness(0.92); }

    /* ─── TICKER ─────────────────────────────────────────── */
    .ticker {
      background: var(--teal);
      color: var(--white);
      height: 40px;
      overflow: hidden;
      position: relative;
    }
    .ticker::before, .ticker::after {
      content: '';
      position: absolute;
      top: 0; bottom: 0;
      width: 80px;
      z-index: 2;
      pointer-events: none;
    }
    .ticker::before { left: 0; background: linear-gradient(to right, var(--teal), transparent); }
    .ticker::after  { right: 0; background: linear-gradient(to left, var(--teal), transparent); }
    .ticker__track {
      display: flex;
      align-items: center;
      height: 100%;
      animation: ticker-scroll 24s linear infinite;
      white-space: nowrap;
      width: max-content;
    }
    .ticker__item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0 40px;
      font-size: 0.85rem;
      font-weight: 500;
    }
    .ticker__dot {
      width: 6px; height: 6px;
      background: oklch(85% 0.08 195);
      border-radius: 50%;
      flex-shrink: 0;
    }
    .ticker__stat { font-weight: 700; }
    @keyframes ticker-scroll {
      0%   { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* ─── HERO ───────────────────────────────────────────── */
    .hero { background: var(--surface); padding: 48px 0; }
    .hero__inner {
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 32px;
      align-items: start;
    }
    .hero__main {
      background: var(--teal);
      border-radius: var(--radius-xl);
      padding: 48px;
      color: var(--white);
      position: relative;
      overflow: hidden;
      min-height: 380px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
    }
    .hero__bg-pattern {
      position: absolute;
      top: 0; right: 0;
      width: 60%;
      height: 100%;
      background: oklch(56% 0.13 195);
      clip-path: polygon(30% 0, 100% 0, 100% 100%, 10% 100%);
      opacity: 0.5;
    }
    .hero__bg-circle {
      position: absolute;
      top: -40px; right: -40px;
      width: 260px; height: 260px;
      border-radius: 50%;
      border: 2px solid oklch(70% 0.08 195);
      opacity: 0.3;
    }
    .hero__badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: oklch(100% 0 0 / 0.15);
      border: 1px solid oklch(100% 0 0 / 0.25);
      border-radius: 999px;
      padding: 6px 14px;
      font-size: 0.8rem;
      font-weight: 600;
      margin-bottom: 20px;
      width: fit-content;
      position: relative;
    }
    .hero__badge-icon {
      width: 20px; height: 20px;
      background: var(--amber);
      border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 0.65rem;
      font-weight: 800;
    }
    .hero__category {
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: oklch(85% 0.08 195);
      margin-bottom: 12px;
      position: relative;
    }
    .hero__title {
      font-size: 2rem;
      font-weight: 700;
      line-height: 1.25;
      margin-bottom: 14px;
      position: relative;
      letter-spacing: -0.5px;
    }
    .hero__subtitle {
      font-size: 1rem;
      color: oklch(92% 0.04 195);
      max-width: 480px;
      position: relative;
      line-height: 1.6;
    }
    .hero__cta-row {
      display: flex;
      gap: 12px;
      margin-top: 28px;
      position: relative;
    }
    .btn--hero { background: var(--white); color: var(--teal); font-weight: 700; padding: 10px 24px; border-radius: var(--radius-sm); font-size: 0.9rem; }
    .btn--hero:hover { background: var(--teal-light); }

    /* Trending sidebar */
    .trending {
      background: var(--white);
      border-radius: var(--radius-xl);
      padding: 28px 24px;
      box-shadow: var(--shadow-md);
    }
    .trending__header {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 20px;
    }
    .trending__label {
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--muted);
    }
    .trending__flame {
      width: 18px; height: 18px;
      color: var(--coral);
    }
    .trending__list { display: flex; flex-direction: column; gap: 0; }
    .trending__item {
      display: flex;
      gap: 14px;
      padding: 14px 0;
      border-bottom: 1px solid var(--border);
      align-items: flex-start;
    }
    .trending__item:last-child { border-bottom: none; padding-bottom: 0; }
    .trending__num {
      font-size: 1.4rem;
      font-weight: 800;
      color: var(--border);
      line-height: 1;
      flex-shrink: 0;
      width: 24px;
      padding-top: 2px;
    }
    .trending__content { flex: 1; }
    .trending__tag {
      display: inline-block;
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--teal);
      background: var(--tag-bg);
      border-radius: 4px;
      padding: 2px 6px;
      margin-bottom: 5px;
    }
    .trending__title {
      font-size: 0.875rem;
      font-weight: 600;
      line-height: 1.4;
      color: var(--charcoal);
      transition: color var(--transition);
    }
    .trending__item:hover .trending__title { color: var(--teal); }

    /* ─── NEWSLETTER CTA ─────────────────────────────────── */
    .newsletter-cta {
      background: linear-gradient(135deg, var(--teal-dark) 0%, var(--teal) 60%, oklch(60% 0.14 175) 100%);
      padding: 64px 0;
    }
    .newsletter-cta__inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }
    .newsletter-cta__text {}
    .newsletter-cta__eyebrow {
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: oklch(85% 0.08 195);
      margin-bottom: 12px;
    }
    .newsletter-cta__heading {
      font-size: 2.25rem;
      font-weight: 700;
      color: var(--white);
      line-height: 1.2;
      letter-spacing: -0.5px;
      margin-bottom: 16px;
    }
    .newsletter-cta__body {
      font-size: 1rem;
      color: oklch(92% 0.04 195);
      line-height: 1.7;
    }
    .newsletter-cta__form {
      background: oklch(100% 0 0 / 0.1);
      border: 1px solid oklch(100% 0 0 / 0.2);
      border-radius: var(--radius-lg);
      padding: 32px;
    }
    .form-row {
      display: flex;
      gap: 10px;
    }
    .form-input {
      flex: 1;
      height: 48px;
      padding: 0 16px;
      border: 1.5px solid oklch(100% 0 0 / 0.3);
      border-radius: var(--radius-sm);
      background: oklch(100% 0 0 / 0.12);
      color: var(--white);
      font-family: var(--font);
      font-size: 0.9rem;
      outline: none;
      transition: border-color var(--transition);
    }
    .form-input::placeholder { color: oklch(85% 0.06 195); }
    .form-input:focus { border-color: oklch(100% 0 0 / 0.6); background: oklch(100% 0 0 / 0.18); }
    .btn--join { background: var(--coral); color: var(--white); font-weight: 700; height: 48px; padding: 0 24px; border-radius: var(--radius-sm); font-size: 0.9rem; white-space: nowrap; }
    .btn--join:hover { filter: brightness(0.92); }
    .privacy-note {
      margin-top: 10px;
      font-size: 0.78rem;
      color: oklch(80% 0.05 195);
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .privacy-note svg { width: 12px; height: 12px; flex-shrink: 0; }

    /* ─── HEALTH TOPICS ──────────────────────────────────── */
    .topics {}
    .section__header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin-bottom: 32px;
    }
    .section__heading {
      font-size: 1.75rem;
      font-weight: 700;
      letter-spacing: -0.4px;
      color: var(--charcoal);
    }
    .view-all {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--teal);
      display: flex;
      align-items: center;
      gap: 4px;
      transition: gap var(--transition);
    }
    .view-all:hover { gap: 8px; }
    .view-all svg { width: 14px; height: 14px; }

    .carousel-wrapper { position: relative; }
    .carousel-track {
      display: flex;
      gap: 20px;
      overflow-x: hidden;
      scroll-behavior: smooth;
      padding: 8px 4px 16px;
    }
    .topic-card {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      flex-shrink: 0;
      cursor: pointer;
    }
    .topic-card__img {
      width: 110px;
      height: 110px;
      border-radius: 50%;
      overflow: hidden;
      border: 3px solid var(--border);
      transition: border-color var(--transition), box-shadow var(--transition);
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .topic-card:hover .topic-card__img {
      border-color: var(--teal);
      box-shadow: 0 0 0 4px oklch(52% 0.12 195 / 0.12);
    }
    .topic-card__icon { font-size: 2.2rem; }
    .topic-card__label {
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--charcoal);
      text-align: center;
      max-width: 110px;
      line-height: 1.3;
      transition: color var(--transition);
    }
    .topic-card:hover .topic-card__label { color: var(--teal); }
    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 40px; height: 40px;
      border-radius: 50%;
      background: var(--white);
      border: 1.5px solid var(--border);
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 2;
      transition: all var(--transition);
    }
    .carousel-btn:hover { background: var(--teal); border-color: var(--teal); color: var(--white); }
    .carousel-btn svg { width: 16px; height: 16px; }
    .carousel-btn--prev { left: -20px; }
    .carousel-btn--next { right: -20px; }

    /* ─── TOOLS ──────────────────────────────────────────── */
    .tools__grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 28px;
    }
    .tools__panel {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 32px;
      box-shadow: var(--shadow-sm);
    }
    .tools__panel--featured {
      background: linear-gradient(135deg, var(--teal-light) 0%, oklch(96% 0.03 175) 100%);
      border-color: oklch(88% 0.06 195);
    }
    .tools__panel-eyebrow {
      font-size: 0.72rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--teal);
      margin-bottom: 8px;
    }
    .tools__panel-heading {
      font-size: 1.4rem;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 10px;
      letter-spacing: -0.3px;
    }
    .tools__panel-body {
      font-size: 0.9rem;
      color: var(--muted);
      line-height: 1.65;
      margin-bottom: 20px;
    }
    .tools__list { display: flex; flex-direction: column; gap: 12px; margin-top: 20px; }
    .tool-item {
      display: flex;
      align-items: flex-start;
      gap: 14px;
      padding: 14px;
      background: var(--white);
      border-radius: var(--radius-md);
      border: 1px solid var(--border);
      transition: all var(--transition);
      cursor: pointer;
    }
    .tool-item:hover { border-color: var(--teal); box-shadow: var(--shadow-md); transform: translateY(-1px); }
    .tool-item__icon {
      width: 40px; height: 40px;
      border-radius: var(--radius-sm);
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 1.2rem;
    }
    .tool-item__content { flex: 1; }
    .tool-item__name {
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--charcoal);
      margin-bottom: 3px;
    }
    .tool-item__desc {
      font-size: 0.8rem;
      color: var(--muted);
      line-height: 1.45;
    }
    .tool-item__arrow {
      width: 16px; height: 16px;
      color: var(--muted);
      flex-shrink: 0;
      margin-top: 2px;
    }
    .drug-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }

    /* ─── RECOMMENDED READS ──────────────────────────────── */
    .tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 32px;
      border-bottom: 2px solid var(--border);
      padding-bottom: 0;
      overflow-x: auto;
      scrollbar-width: none;
    }
    .tabs::-webkit-scrollbar { display: none; }
    .tab-btn {
      padding: 10px 18px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--muted);
      border-radius: var(--radius-sm) var(--radius-sm) 0 0;
      transition: all var(--transition);
      white-space: nowrap;
      border-bottom: 2px solid transparent;
      margin-bottom: -2px;
    }
    .tab-btn:hover { color: var(--charcoal); background: var(--surface); }
    .tab-btn--active { color: var(--teal); border-bottom-color: var(--teal); background: transparent; }

    .articles-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .article-card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      overflow: hidden;
      transition: all var(--transition);
      cursor: pointer;
    }
    .article-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
    .article-card__img {
      height: 160px;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.5rem;
      overflow: hidden;
      position: relative;
    }
    .article-card__img--fitness    { background: oklch(94% 0.05 145); }
    .article-card__img--mental     { background: oklch(94% 0.05 280); }
    .article-card__img--nutrition  { background: oklch(94% 0.05 100); }
    .article-card__img--product    { background: oklch(94% 0.05 40); }
    .article-card__img--skin       { background: oklch(94% 0.05 20); }
    .article-card__body { padding: 18px; }
    .article-card__category {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--teal);
      background: var(--tag-bg);
      border-radius: 4px;
      padding: 2px 7px;
      display: inline-block;
      margin-bottom: 8px;
    }
    .article-card__title {
      font-size: 0.95rem;
      font-weight: 600;
      line-height: 1.4;
      color: var(--charcoal);
      margin-bottom: 8px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .article-card__meta {
      font-size: 0.78rem;
      color: var(--muted);
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .article-card__reviewed {
      display: flex;
      align-items: center;
      gap: 4px;
      font-size: 0.72rem;
      color: var(--teal);
      background: var(--tag-bg);
      border-radius: 4px;
      padding: 2px 6px;
    }
    .article-card__reviewed svg { width: 10px; height: 10px; }

    /* Tab pane */
    .tab-pane { display: none; }
    .tab-pane--active { display: block; }

    /* ─── TRUST SECTION ──────────────────────────────────── */
    .trust {
      background: var(--charcoal);
      padding: 80px 0;
    }
    .trust__heading {
      font-size: 2rem;
      font-weight: 700;
      color: var(--white);
      text-align: center;
      margin-bottom: 48px;
      letter-spacing: -0.4px;
      max-width: 600px;
      margin-left: auto;
      margin-right: auto;
    }
    .trust__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }
    .trust__pillar {
      text-align: center;
      padding: 0 8px;
    }
    .trust__pillar-icon {
      width: 64px; height: 64px;
      border-radius: var(--radius-md);
      background: oklch(28% 0.02 195);
      border: 1px solid oklch(40% 0.04 195);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
      font-size: 1.8rem;
    }
    .trust__pillar-title {
      font-size: 1rem;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 10px;
    }
    .trust__pillar-body {
      font-size: 0.875rem;
      color: oklch(70% 0.02 260);
      line-height: 1.65;
    }

    /* ─── FEATURED PROGRAMS ──────────────────────────────── */
    .programs__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }
    .program-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      position: relative;
      height: 220px;
      cursor: pointer;
      transition: transform var(--transition);
    }
    .program-card:hover { transform: translateY(-3px); }
    .program-card:hover .program-card__overlay { opacity: 0.85; }
    .program-card__bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
    }
    .program-card__bg--1 { background: linear-gradient(135deg, oklch(88% 0.07 20), oklch(92% 0.04 30)); }
    .program-card__bg--2 { background: linear-gradient(135deg, oklch(82% 0.07 195), oklch(90% 0.05 180)); }
    .program-card__bg--3 { background: linear-gradient(135deg, oklch(88% 0.07 60), oklch(92% 0.04 50)); }
    .program-card__bg--4 { background: linear-gradient(135deg, oklch(88% 0.07 280), oklch(92% 0.04 265)); }
    .program-card__overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, oklch(18% 0.01 260 / 0.85) 0%, transparent 60%);
      transition: opacity var(--transition);
    }
    .program-card__content {
      position: absolute;
      bottom: 0; left: 0; right: 0;
      padding: 18px;
      color: var(--white);
    }
    .program-card__tag {
      font-size: 0.65rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: oklch(80% 0.08 60);
      margin-bottom: 6px;
    }
    .program-card__title {
      font-size: 0.95rem;
      font-weight: 700;
      line-height: 1.35;
    }

    /* ─── LATEST VIDEOS ──────────────────────────────────── */
    .videos__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }
    .video-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      cursor: pointer;
      transition: transform var(--transition);
    }
    .video-card:hover { transform: translateY(-2px); }
    .video-card__thumb {
      height: 150px;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.5rem;
    }
    .video-card__thumb--1 { background: linear-gradient(135deg, oklch(92% 0.06 145), oklch(96% 0.03 155)); }
    .video-card__thumb--2 { background: linear-gradient(135deg, oklch(88% 0.06 20), oklch(92% 0.04 30)); }
    .video-card__thumb--3 { background: linear-gradient(135deg, oklch(88% 0.06 280), oklch(92% 0.04 265)); }
    .video-card__thumb--4 { background: linear-gradient(135deg, oklch(92% 0.05 50), oklch(96% 0.03 60)); }
    .video-card__play {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      background: oklch(18% 0.01 260 / 0.2);
      transition: background var(--transition);
    }
    .video-card:hover .video-card__play { background: oklch(18% 0.01 260 / 0.35); }
    .play-btn {
      width: 44px; height: 44px;
      border-radius: 50%;
      background: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
    }
    .play-btn svg { width: 16px; height: 16px; color: var(--teal); margin-left: 2px; }
    .video-card__body { padding: 14px; background: var(--white); border: 1px solid var(--border); border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md); }
    .video-card__title { font-size: 0.875rem; font-weight: 600; color: var(--charcoal); line-height: 1.4; }

    /* ─── FOOTER ─────────────────────────────────────────── */
