      background: var(--charcoal);
      color: var(--white);
      padding: 64px 0 0;
    }
    .footer__newsletter {
      background: oklch(24% 0.01 260);
      border-radius: var(--radius-xl);
      padding: 40px 48px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
      align-items: center;
      margin-bottom: 56px;
