      font-size: 1.2rem;
      color: var(--white);
      margin-bottom: 8px;
    }
    .footer__form { display: flex; gap: 10px; }
    .footer__input {
      flex: 1;
      height: 44px;
      padding: 0 14px;
      border: 1.5px solid oklch(40% 0.02 260);
      border-radius: var(--radius-sm);
      background: oklch(28% 0.01 260);
      color: var(--white);
      font-family: var(--font);
      font-size: 0.875rem;
      outline: none;
      transition: border-color var(--transition);
