    .footer__input::placeholder { color: oklch(55% 0.01 260); }
    .footer__input:focus { border-color: var(--teal); }
    .btn--signup { background: var(--teal); color: var(--white); font-weight: 700; height: 44px; padding: 0 20px; border-radius: var(--radius-sm); font-size: 0.875rem; white-space: nowrap; }
    .btn--signup:hover { background: var(--teal-dark); }

    .footer__main {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 48px;
      padding-bottom: 32px;
      border-bottom: 1px solid oklch(30% 0.01 260);
    }
    .footer__brand {}
    .footer__logo { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; }
    .footer__logo-mark {
      width: 32px; height: 32px;
      background: var(--teal);
      border-radius: 8px;
      display: flex; align-items: center; justify-content: center;
      color: var(--white);
    }
    .footer__logo-mark svg { width: 18px; height: 18px; }
    .footer__logo-text { font-size: 1.1rem; font-weight: 700; color: var(--white); }
    .footer__logo-text span { color: var(--teal); }
    .footer__tagline { font-size: 0.875rem; color: oklch(65% 0.01 260); max-width: 280px; line-height: 1.6; }
    .footer__social { display: flex; gap: 10px; margin-top: 20px; }
    .social-btn {
      width: 36px; height: 36px;
      border-radius: 50%;
      background: oklch(28% 0.01 260);
      border: 1px solid oklch(35% 0.01 260);
      display: flex; align-items: center; justify-content: center;
      color: oklch(70% 0.01 260);
      font-size: 0.75rem;
      font-weight: 700;
      transition: all var(--transition);
    }
    .social-btn:hover { background: var(--teal); border-color: var(--teal); color: var(--white); }

    .footer__links { display: flex; flex-direction: column; gap: 8px; align-items: flex-end; }
    .footer__links a {
      font-size: 0.82rem;
      color: oklch(65% 0.01 260);
      transition: color var(--transition);
    }
    .footer__links a:hover { color: var(--teal); }
    .footer__links-row { display: flex; gap: 16px; flex-wrap: wrap; justify-content: flex-end; }

    .footer__bottom {
      padding: 20px 0;
      display: flex;
      justify-content: center;
    }
    .footer__legal {
      font-size: 0.78rem;
      color: oklch(45% 0.01 260);
      text-align: center;
      line-height: 1.7;
      max-width: 700px;
    }

    /* ─── RESPONSIVE ─────────────────────────────────────── */
    @media (max-width: 1024px) {
      .trust__grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
      .programs__grid { grid-template-columns: repeat(2, 1fr); }
      .videos__grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 768px) {
      .header__inner { gap: 16px; }
      .nav { display: none; }
      .hero__inner { grid-template-columns: 1fr; }
      .hero__main { min-height: 280px; padding: 32px; }
      .newsletter-cta__inner { grid-template-columns: 1fr; gap: 28px; }
      .newsletter-cta__heading { font-size: 1.6rem; }
      .tools__grid { grid-template-columns: 1fr; }
