<script>
  /* ── Mega-menu toggle ── */
  function toggleNav(id) {
    const item = document.getElementById(id);
    const isOpen = item.classList.contains('nav__item--open');

    // Close all
    document.querySelectorAll('.nav__item--open').forEach(el => {
      el.classList.remove('nav__item--open');
      el.querySelector('[aria-expanded]').setAttribute('aria-expanded', 'false');
    });

    if (!isOpen) {
      item.classList.add('nav__item--open');
      item.querySelector('[aria-expanded]').setAttribute('aria-expanded', 'true');
    }
  }

  // Close dropdowns on outside click
  document.addEventListener('click', e => {
    if (!e.target.closest('.nav__item')) {
      document.querySelectorAll('.nav__item--open').forEach(el => {
        el.classList.remove('nav__item--open');
        el.querySelector('[aria-expanded]').setAttribute('aria-expanded', 'false');
      });
    }
  });

  // Close on Escape
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      document.querySelectorAll('.nav__item--open').forEach(el => {
        el.classList.remove('nav__item--open');
        el.querySelector('[aria-expanded]').setAttribute('aria-expanded', 'false');
      });
    }
  });

  /* ── Recommended Reads tabs ── */
  function switchTab(btn, paneId) {
    // Update buttons
    document.querySelectorAll('.tab-btn').forEach(b => {
      b.classList.remove('tab-btn--active');
      b.setAttribute('aria-selected', 'false');
    });
    btn.classList.add('tab-btn--active');
    btn.setAttribute('aria-selected', 'true');

    // Update panes
    document.querySelectorAll('.tab-pane').forEach(p => p.classList.remove('tab-pane--active'));
    document.getElementById(paneId).classList.add('tab-pane--active');
  }

  /* ── Health topics carousel ── */
  function scrollCarousel(trackId, direction) {
    const track = document.getElementById(trackId);
    const itemWidth = 130 + 20; // card width + gap
    track.scrollBy({ left: direction * itemWidth * 2, behavior: 'smooth' });
  }

  /* ── Newsletter signup ── */
  function handleNewsletterSignup(btn) {
    const form = btn.closest('.newsletter-cta__form, .footer__newsletter, .footer');
    const input = form ? form.querySelector('input[type="email"]') : null;

    if (input && input.value && input.value.includes('@')) {
      const original = btn.textContent;
      btn.textContent = '✓ Subscribed!';
      btn.style.background = 'oklch(52% 0.12 145)';
      btn.disabled = true;
      input.value = '';
      setTimeout(() => {
        btn.textContent = original;
        btn.style.background = '';
        btn.disabled = false;
      }, 3000);
    } else if (input) {
      input.style.borderColor = 'oklch(65% 0.17 30)';
      input.focus();
      setTimeout(() => input.style.borderColor = '', 2000);
    }
  }
</script>
